import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
}
const defaults = freeze({
  server: { host: 'localhost', port: 8080, tls: { enabled: true, cert: { path: 'old', format: 'pem' } } },
  logging: { level: 'info', outputs: { file: true, console: true } },
  tags: ['a', 'b'], untouched: { enabled: true }
});
const overrides = freeze({
  server: { port: 9090, tls: { cert: { path: 'new' }, verify: false } },
  logging: { outputs: { console: false, remote: true } }, tags: ['c'], added: { x: 1 }
});
assert.deepEqual(mergeConfig(defaults, overrides), {
  server: { host: 'localhost', port: 9090, tls: { enabled: true, cert: { path: 'new', format: 'pem' }, verify: false } },
  logging: { level: 'info', outputs: { file: true, console: false, remote: true } },
  tags: ['c'], untouched: { enabled: true }, added: { x: 1 }
});
assert.deepEqual(mergeConfig({ a: { b: { c: 1 } } }, { a: {} }), { a: { b: { c: 1 } } });
assert.deepEqual(mergeConfig({ a: {} }, { a: { b: { c: 1 } } }), { a: { b: { c: 1 } } });
assert.deepEqual(mergeConfig({ a: { keep: true, b: { keep: true, c: 1 } } }, { a: { b: null } }), { a: { keep: true, b: null } });

// Exercise repeated nested merges beyond just the first few levels.
let left = { retained: 1, replaced: 'before' };
let right = { replaced: 'after', added: 2 };
let expected = { retained: 1, replaced: 'after', added: 2 };
for (let i = 0; i < 40; i++) {
  left = { child: left, sibling: i };
  right = { child: right };
  expected = { child: expected, sibling: i };
}
freeze(left); freeze(right);
assert.deepEqual(mergeConfig(left, right), expected);

// Null-prototype dictionaries are also plain objects; no result prototype is prescribed.
const dictionary = Object.assign(Object.create(null), { keep: 1, replace: 2 });
const patch = Object.assign(Object.create(null), { replace: 3, add: 4 });
const merged = mergeConfig({ dictionary }, { dictionary: patch }).dictionary;
assert.equal(merged.keep, 1);
assert.equal(merged.replace, 3);
assert.equal(merged.add, 4);
assert.deepEqual(Object.keys(dictionary).sort(), ['keep', 'replace']);
assert.equal(dictionary.replace, 2);
assert.equal(patch.replace, 3);
console.log('recursive merge checks passed');

import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }), { level: 'debug', color: true, file: 'app.log' });
assert.deepEqual(mergeConfig({}, {}), {});
assert.deepEqual(mergeConfig({ a: 1 }, {}), { a: 1 });
assert.deepEqual(mergeConfig({}, { a: 1 }), { a: 1 });

const fn = () => 1;
class Box { constructor() { this.x = 1; } }
const values = [null, undefined, false, true, 0, 9, '', 'value', [], ['c'], new Date(0), /x/, fn, new Box()];
for (const value of values) {
  const defaults = Object.freeze({ item: Object.freeze({ keep: 1, other: 2 }), stable: 3 });
  const overrides = Object.freeze({ item: value });
  const result = mergeConfig(defaults, overrides);
  assert.strictEqual(result.item, value, 'non-plain overrides replace whole values');
  assert.equal(result.stable, 3);
  assert.deepEqual(defaults.item, { keep: 1, other: 2 });
  assert.strictEqual(overrides.item, value);
}
for (const value of values) {
  const defaults = { item: value };
  const overrides = { item: { newKey: 1 } };
  assert.deepEqual(mergeConfig(defaults, overrides), { item: { newKey: 1 } });
  assert.strictEqual(defaults.item, value);
  assert.deepEqual(overrides, { item: { newKey: 1 } });
}
const inherited = Object.create({ inherited: 2 });
inherited.own = 1;
assert.deepEqual(mergeConfig(inherited, { extra: 3 }), { own: 1, extra: 3 });
assert.deepEqual(mergeConfig({ keep: 4 }, inherited), { keep: 4, own: 1 });
const symbol = Symbol('key');
assert.deepEqual(mergeConfig({ [symbol]: 1, keep: 2 }, { [symbol]: 3 }), { [symbol]: 3, keep: 2 });
const defaults = { a: 1, untouched: { b: 2 } };
const overrides = { a: 3, added: { c: 4 } };
const beforeDefaults = structuredClone(defaults);
const beforeOverrides = structuredClone(overrides);
mergeConfig(defaults, overrides);
assert.deepEqual(defaults, beforeDefaults);
assert.deepEqual(overrides, beforeOverrides);
console.log('compatibility checks passed');
